sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Breast' AND "Included in MA" = 'No' AND "Type of combination" = 'ICI+Chemo';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Breast' AND "Included in MA" = 'No' AND "Type of combination" = 'ICI+Chemo'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_platinum_agent(source_value) AS "platinum_agent"
FROM base;
